/** The initials of a name: the first letters of its first and last word („Anna Keller“ → „AK“). */
fun sbInitials(name: String): String {
    val words = name.split(' ').filter { it.isNotBlank() }
    return listOfNotNull(words.firstOrNull(), words.drop(1).lastOrNull()).joinToString("") { it.take(1).uppercase() }
}

/**
 * Avatar (spec/02 §3.13): [initials] in label (small: labelSmall at the label weight) in text, in a circle of 40 dp
 * (small: 32 dp) with a 1 dp borderStrong ring, no fill; the circle tells people from app signs. The circle grows
 * with the text scale (it holds text). TalkBack reads [name], never the initials.
 */
/** D132: offline is a dashed ring and muted initials; Shield badge is provisional, agent. */
@Composable
fun SbAvatar(
    name: String, modifier: Modifier = Modifier, initials: String = sbInitials(name), small: Boolean = false,
    offline: Boolean = false, moderation: Boolean = false,
    offlineWord: String = sbMessages().avatarOffline, moderationWord: String = sbMessages().avatarModeration,
) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    val edge = (if (small) t.space.s8 else t.space.s10) * sbTextScale()
    val spoken = listOfNotNull(name, moderationWord.takeIf { moderation }, offlineWord.takeIf { offline }).joinToString(", ")
    Box(
        modifier.size(edge).drawWithContent {
            val stroke = t.borderWidth.control.toPx()
            drawCircle(c.borderStrong, radius = (size.minDimension - stroke) / 2f,
                style = androidx.compose.ui.graphics.drawscope.Stroke(stroke,
                    pathEffect = if (offline) androidx.compose.ui.graphics.PathEffect.dashPathEffect(floatArrayOf(t.space.s1.toPx(), t.space.s1.toPx())) else null))
            drawContent()
        }.clearAndSetSemantics { contentDescription = spoken },
        contentAlignment = Alignment.Center,
    ) {
        Text(initials, style = if (small) ty.labelSmall.copy(fontWeight = ty.label.fontWeight) else ty.label,
            color = if (offline) c.textMuted else c.text, maxLines = 1)
        // outside the initials: it sits on the ring, a third of it past the corner (small avatar too)
        if (moderation) Icon(SebaroIcons.Outline16.Shield, null, tint = c.text,
            modifier = Modifier.align(Alignment.BottomEnd).offset(t.size.iconSm * sbTextScale() / 3, t.size.iconSm * sbTextScale() / 3)
                .size(t.size.iconSm * sbTextScale()).background(c.bg, t.shapes.pill))
    }
}

@Deprecated("Binary bridge before presence and role", level = DeprecationLevel.HIDDEN)
@Composable
fun SbAvatar(name: String, modifier: Modifier = Modifier, initials: String = sbInitials(name), small: Boolean = false) =
    SbAvatar(name, modifier, initials, small, offline = false, moderation = false)

/** Default words without extending the SbMessages constructor/copy ABI; callers localise via the avatar arguments. */
val SbMessages.avatarOffline: String get() = "offline"
val SbMessages.avatarModeration: String get() = "Moderation"

/** Avatars in a row, 4 dp apart (sb-avatars), the group named by [label] („Auf der Tafel“). */
@Composable
fun SbAvatars(label: String, modifier: Modifier = Modifier, content: @Composable () -> Unit) {
    Row(
        modifier.semantics {
            contentDescription = label
            isTraversalGroup = true
        },
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(SebaroTheme.tokens.space.s1),
    ) { content() }
}
